css:
.toggle-container {
  perspective: 1800px;
  position: relative;
}

.toggle-container input {
  display: none; /* Hide default checkbox */
}

.toggle-button {
  position: relative;
  width: 140px;
  height: 60px;
  background: linear-gradient(
    145deg,
    #4a4a3a,
    #5a5a4a
  ); /* Brushed metal base */
  border-radius: 12px; /* Material Design rounded corners */
  box-shadow: 
                /* Neumorphic/Material shadows */
    8px 8px 16px rgba(0, 0, 0, 0.4),
    -8px -8px 16px rgba(255, 140, 0, 0.1),
    /* Subtle orange tint */ /* Skeuomorphic inset for texture */ inset 0 2px
      4px rgba(255, 255, 255, 0.1),
    inset 0 -2px 4px rgba(0, 0, 0, 0.5);
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); /* Material Design easing */
  transform-style: preserve-3d;
  transform: translateZ(0);
}

/* Engraved track with micro-texture */
.toggle-button::after {
  content: "";
  position: absolute;
  width: 128px;
  height: 48px;
  background: linear-gradient(
    145deg,
    rgba(255, 69, 0, 0.2),
    rgba(0, 0, 0, 0.4)
  );
  border-radius: 8px;
  top: 6px;
  left: 6px;
  box-shadow:
    inset 0 0 10px rgba(0, 0, 0, 0.6),
    inset 0 0 3px rgba(255, 140, 0, 0.2),
    /* Orange-red accent */ inset 0 0 1px rgba(255, 255, 255, 0.05); /* Micro-texture */
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
}

/* Textured, gem-like knob */
.toggle-button::before {
  content: "";
  position: absolute;
  width: 54px;
  height: 54px;
  background: radial-gradient(
    circle at 30% 20%,
    #ff4500,
    #ff8c00
  ); /* Orange-red gradient */
  border-radius: 20%;
  top: 3px;
  left: 3px;
  box-shadow: 
                /* Neumorphic/Material depth */
    4px 4px 8px rgba(0, 0, 0, 0.5),
    -4px -4px 8px rgba(255, 255, 255, 0.15),
    /* Skeuomorphic texture */ inset 0 -1px 3px rgba(0, 0, 0, 0.6),
    inset 0 1px 3px rgba(255, 255, 255, 0.3),
    /* Polished highlight */ 1px 1px 2px rgba(255, 255, 255, 0.2);
  transition: all 0.4s cubic-bezier(0.77, -0.4, 0.3, 1.4); /* Elastic, Material-inspired bounce */
  transform: translateZ(20px) scale(1);
  z-index: 2;
}

/* Subtle texture overlay for knob */
.toggle-button .texture {
  position: absolute;
  width: 54px;
  height: 54px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.1), transparent);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  opacity: 0.4;
  transition: all 0.4s cubic-bezier(0.77, -0.4, 0.3, 1.4);
  transform: translateZ(21px);
  pointer-events: none;
}

/* Minimal glow for realism */
.toggle-button .glow {
  position: absolute;
  width: 60px;
  height: 60px;
  background: radial-gradient(
    circle,
    rgba(255, 140, 0, 0.2),
    transparent
  ); /* Subtle orange-red glow */
  border-radius: 50%;
  top: 0;
  left: 0;
  opacity: 0;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  transform: translateZ(15px);
  pointer-events: none;
}

/* Checked state */
.toggle-container input:checked ~ .toggle-button {
  background: linear-gradient(
    145deg,
    #3a4a3a,
    #4a5a4a
  ); /* Yellow-green metallic */
  box-shadow:
    8px 8px 16px rgba(0, 0, 0, 0.4),
    -8px -8px 16px rgba(154, 205, 50, 0.1),
    /* Subtle yellow-green tint */ inset 0 2px 4px rgba(255, 255, 255, 0.1),
    inset 0 -2px 4px rgba(0, 0, 0, 0.5);
}

.toggle-container input:checked ~ .toggle-button::before {
  left: 80px;
  background: radial-gradient(
    circle at 30% 20%,
    #9acd32,
    #32cd32
  ); /* Yellow-green gradient */
  transform: translateZ(20px) rotate(180deg) scale(1.05); /* Subtle spin and pulse */
  box-shadow:
    4px 4px 8px rgba(0, 0, 0, 0.5),
    -4px -4px 8px rgba(255, 255, 255, 0.15),
    inset 0 -1px 3px rgba(0, 0, 0, 0.6),
    inset 0 1px 3px rgba(255, 255, 255, 0.3),
    1px 1px 2px rgba(255, 255, 255, 0.2);
}

.toggle-container input:checked ~ .toggle-button::after {
  background: linear-gradient(
    145deg,
    rgba(154, 205, 50, 0.2),
    rgba(0, 0, 0, 0.4)
  );
  box-shadow:
    inset 0 0 10px rgba(0, 0, 0, 0.6),
    inset 0 0 3px rgba(154, 205, 50, 0.2),
    inset 0 0 1px rgba(255, 255, 255, 0.05);
}

.toggle-container input:checked ~ .toggle-button .glow {
  background: radial-gradient(
    circle,
    rgba(154, 205, 50, 0.2),
    transparent
  ); /* Subtle yellow-green glow */
  left: 74px;
  opacity: 0.3;
}

.toggle-container input:checked ~ .toggle-button .texture {
  left: 80px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.15), transparent);
}

/* Hover effect (Material Design elevation) */
.toggle-button:hover {
  box-shadow:
    10px 10px 20px rgba(0, 0, 0, 0.5),
    -10px -10px 20px rgba(255, 140, 0, 0.15),
    inset 0 2px 4px rgba(255, 255, 255, 0.1),
    inset 0 -2px 4px rgba(0, 0, 0, 0.5);
  transform: translateZ(5px);
}

.toggle-button:hover::before {
  transform: translateZ(25px) scale(1.03);
  box-shadow:
    5px 5px 10px rgba(0, 0, 0, 0.5),
    -5px -5px 10px rgba(255, 255, 255, 0.2),
    inset 0 -1px 3px rgba(0, 0, 0, 0.6),
    inset 0 1px 3px rgba(255, 255, 255, 0.3);
}

/* Active effect (Material Design press feedback) */
.toggle-button:active::before {
  transform: translateZ(15px) scale(0.97);
  box-shadow:
    2px 2px 4px rgba(0, 0, 0, 0.6),
    -2px -2px 4px rgba(255, 255, 255, 0.1),
    inset 0 -1px 3px rgba(0, 0, 0, 0.7),
    inset 0 1px 3px rgba(255, 255, 255, 0.3);
}

/* Micro-interaction animations */
@keyframes track-vibrate {
  0%,
  100% {
    transform: translateZ(0) translateY(0);
  }
  50% {
    transform: translateZ(0) translateY(-0.5px);
  }
}

@keyframes knob-pulse {
  0%,
  100% {
    transform: translateZ(20px) scale(1);
  }
  50% {
    transform: translateZ(20px) scale(1.04);
  }
}

@keyframes track-etch {
  0%,
  100% {
    box-shadow: inset 0 0 6px rgba(255, 140, 0, 0.15);
  }
  50% {
    box-shadow: inset 0 0 9px rgba(255, 140, 0, 0.3);
  }
}

.toggle-button {
  animation: track-vibrate 0.08s ease-in-out 0.2s 3; /* Subtle haptic feedback */
}

.toggle-container input:checked ~ .toggle-button::before {
  animation: knob-pulse 1.8s infinite ease-in-out;
}

.toggle-container input:checked ~ .toggle-button::after {
  animation: track-etch 2.2s infinite ease-in-out;
}
